"""Generate common/sin_table.h: one sine cycle, 256 points, signed 16 bit.

The mod LFO in a DLS drives pitch (vibrato) and gain (tremolo) by an
amount the bank states in cents and decibels, and the oscillator has to
run at whatever rate the bank asks for. 256 points on a 32-bit phase
top byte is 0.14 percent amplitude error on a linear interpolator's
worth of a table this size, and it costs 512 bytes.

    python3 tools/gen_sin.py > common/sin_table.h
"""
import math
import sys

N = 256
OUT = sys.stdout

OUT.write(
    "/* sin_table.h - GENERATED by tools/gen_sin.py. Do not edit.\n"
    " *\n"
    " * One sine cycle, 256 points, -32768..32767. Indexed by the top\n"
    " * byte of a 32-bit phase, which is what keeps the mod LFO's own\n"
    " * rate independent of the buffer size. See the generator.\n"
    " */\n"
    "#ifndef KAC_SIN_TABLE_H\n"
    "#define KAC_SIN_TABLE_H\n\n")
OUT.write("static const short sin_tbl[%d] = {\n" % N)
vals = [int(round(32767.0 * math.sin(2.0 * math.pi * i / N)))
        for i in range(N)]
for i in range(0, N, 8):
    OUT.write("    " + " ".join("%6d," % v for v in vals[i:i + 8]) + "\n")
OUT.write("};\n\n#endif /* KAC_SIN_TABLE_H */\n")

assert vals[0] == 0, vals[0]
assert vals[N // 4] > 32760, vals[N // 4]
assert vals[N // 2] == 0, vals[N // 2]
assert vals[3 * N // 4] < -32760, vals[3 * N // 4]
